insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-derechos-tiene-un-consumidor-ante-un-producto-defectuoso','derecho',array['negocios','sociedad']::text[],'¿Qué derechos tiene un consumidor ante un producto defectuoso?','Entiende qué puede exigir una persona cuando compra algo que llega fallado o no funciona: reparación, cambio o devolución del dinero, con casos cotidianos y plazos.','Guía','~15 h',15,array['Consumidor','Garantía']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho economia administracion comunicaciones contabilidad ingenieria industrial marketing educacion lectura de normas. analisis de casos. redaccion clara. diseno de guias. portal de la autoridad de proteccion al consumidor. un editor de documentos. un editor de esquemas.',$a1sld${"id": "que-derechos-tiene-un-consumidor-ante-un-producto-defectuoso", "area": "derecho", "areas2": ["negocios", "sociedad"], "titulo": "¿Qué derechos tiene un consumidor ante un producto defectuoso?", "resumen": "Entiende qué puede exigir una persona cuando compra algo que llega fallado o no funciona: reparación, cambio o devolución del dinero, con casos cotidianos y plazos.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Consumidor", "Garantía"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Economía", "Administración", "Comunicaciones", "Contabilidad", "Ingeniería Industrial", "Marketing", "Educación"], "problema": ["Casi todos hemos comprado algo que falla a los pocos días: un celular, una laptop o unos zapatos. Muchas personas no saben si pueden exigir un cambio o la devolución, ni a quién acudir, y terminan resignándose.", "Conocer la regla básica, qué se garantiza, por cuánto tiempo y qué pruebas guardar, convierte una situación frustrante en un trámite manejable."], "desarrollar": ["Con fuentes oficiales, como el código de protección al consumidor y las guías de la autoridad, resume qué derechos tiene quien compra un producto defectuoso, qué opciones puede pedir y qué plazos existen.", "Redacta cinco casos cotidianos inventados, como un celular que no enciende o una prenda que se destiñe, y para cada uno explica qué podría reclamar la persona, qué documentos guardar y adónde acudir."], "ampliaciones": [{"titulo": "Árbol de decisión", "aporta": "dibuja un esquema simple que diga qué hacer según el caso."}, {"titulo": "Garantía legal frente a garantía comercial", "aporta": "explica la diferencia con ejemplos."}, {"titulo": "Plantilla de reclamo", "aporta": "crea un modelo de carta o formulario para presentar el reclamo."}], "objetivos": ["Reconocer derechos básicos del consumidor.", "Aplicarlos a casos cotidianos.", "Identificar pruebas y plazos.", "Explicar el procedimiento con claridad."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Redacción clara.", "Diseño de guías."], "herramientas": ["Portal de la autoridad de protección al consumidor.", "Un editor de documentos.", "Un editor de esquemas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "La misma lógica de derechos y pasos sirve para explicar qué hacer ante un servicio mal prestado, una factura equivocada o una compra por internet."}$a1sld$::jsonb,3),
('comparando-las-garantias-de-distintos-productos-y-servicios','derecho',array['negocios']::text[],'Comparando las garantías de distintos productos y servicios','Compara qué garantías ofrecen distintos productos y servicios, cuánto duran, qué cubren y qué excluyen, y descubre cuál protege realmente más a quien compra.','Análisis','~18 h',18,array['Garantías','Consumo']::text[],array['investigar']::text[],'publicos',NULL,'derecho economia administracion marketing contabilidad ingenieria industrial comunicaciones estadistica lectura de documentos. analisis comparativo. pensamiento critico. comunicacion clara. una tabla comparativa. paginas publicas de empresas. hoja de calculo.',$a2sld${"id": "comparando-las-garantias-de-distintos-productos-y-servicios", "area": "derecho", "areas2": ["negocios"], "titulo": "Comparando las garantías de distintos productos y servicios", "resumen": "Compara qué garantías ofrecen distintos productos y servicios, cuánto duran, qué cubren y qué excluyen, y descubre cuál protege realmente más a quien compra.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Garantías", "Consumo"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Economía", "Administración", "Marketing", "Contabilidad", "Ingeniería Industrial", "Comunicaciones", "Estadística"], "problema": ["Una garantía de un año no siempre significa lo mismo: algunas cubren el producto completo y otras solo ciertas piezas, y casi todas tienen condiciones que se leen poco, como no abrir el equipo o usar solo centros autorizados.", "Comparar garantías permite ver qué promete cada vendedor y qué parte es publicidad."], "desarrollar": ["Elige cinco productos o servicios de uso común, como un celular, un electrodoméstico, una suscripción o una reparación, y reúne con información pública sus condiciones de garantía: duración, cobertura, exclusiones y cómo se hace efectiva.", "Compáralas en una tabla, señala las cláusulas que más limitan al consumidor y explica cuál ofrece mejor protección real, con los límites de tu comparación."], "ampliaciones": [{"titulo": "Lo que dice la ley", "aporta": "contrasta cada garantía con lo mínimo que la norma exige."}, {"titulo": "Lenguaje claro", "aporta": "reescribe una garantía en palabras sencillas."}, {"titulo": "Puntaje de garantía", "aporta": "diseña un indicador para calificar garantías."}], "objetivos": ["Reunir condiciones de garantía.", "Compararlas con criterios.", "Identificar cláusulas limitantes.", "Concluir con argumentos."], "habilidades": ["Lectura de documentos.", "Análisis comparativo.", "Pensamiento crítico.", "Comunicación clara."], "herramientas": ["Una tabla comparativa.", "Páginas públicas de empresas.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "No califiques a marcas concretas como buenas o malas sin sustento: describe lo que dicen sus documentos públicos.", "Cita la fuente y la fecha de cada garantía."], "otroSector": "La misma comparación sirve para seguros, contratos de internet o planes de telefonía."}$a2sld$::jsonb,4),
('que-hacer-cuando-un-servicio-no-cumple-lo-prometido-casos-cotidi','derecho',array['negocios','sociedad']::text[],'¿Qué hacer cuando un servicio no cumple lo prometido? Casos cotidianos','Analiza casos de la vida diaria donde un servicio no cumple lo ofrecido, como un internet lento, un delivery tardío o un curso sin el contenido prometido, y arma una guía de qué hacer en cada uno.','Guía','~18 h',18,array['Servicios','Reclamos']::text[],array['investigar','resolver']::text[],'ficticios',NULL,'derecho economia administracion trabajo social comunicaciones sociologia ingenieria de sistemas educacion analisis de casos. lectura de normas. redaccion clara. pensamiento practico. un editor de documentos. portal de la autoridad de proteccion al consumidor. casos inventados.',$a3sld${"id": "que-hacer-cuando-un-servicio-no-cumple-lo-prometido-casos-cotidi", "area": "derecho", "areas2": ["negocios", "sociedad"], "titulo": "¿Qué hacer cuando un servicio no cumple lo prometido? Casos cotidianos", "resumen": "Analiza casos de la vida diaria donde un servicio no cumple lo ofrecido, como un internet lento, un delivery tardío o un curso sin el contenido prometido, y arma una guía de qué hacer en cada uno.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Servicios", "Reclamos"], "intencion": ["investigar", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Derecho", "Economía", "Administración", "Trabajo Social", "Comunicaciones", "Sociología", "Ingeniería de Sistemas", "Educación"], "problema": ["Los servicios fallan: el internet no llega a la velocidad contratada, el taller no cumple el plazo o el curso no era lo que decía el anuncio. En esos momentos muchas personas no saben qué hacer primero ni qué pruebas reunir.", "Revisar casos concretos ayuda a reconocer patrones y a tener un plan antes de que ocurra."], "desarrollar": ["Redacta cinco casos cotidianos inventados donde un servicio incumple lo prometido, y para cada uno identifica qué se ofreció, qué se recibió, qué pruebas hay y qué derechos podrían estar en juego.", "Escribe para cada caso los pasos recomendados, desde reunir pruebas y reclamar a la empresa hasta acudir a la autoridad, y resume todo en una guía de una página."], "ampliaciones": [{"titulo": "Pruebas", "aporta": "arma una lista de qué guardar según el tipo de servicio."}, {"titulo": "Tiempos", "aporta": "añade cuánto suele tardar cada paso."}, {"titulo": "Cuándo no vale la pena", "aporta": "analiza cuándo un reclamo cuesta más de lo que se recupera."}], "objetivos": ["Analizar casos de incumplimiento.", "Identificar pruebas y derechos.", "Definir pasos de acción.", "Redactar una guía breve."], "habilidades": ["Análisis de casos.", "Lectura de normas.", "Redacción clara.", "Pensamiento práctico."], "herramientas": ["Un editor de documentos.", "Portal de la autoridad de protección al consumidor.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales.", "No incluyas nombres de empresas reales en los casos inventados."], "otroSector": "El mismo enfoque de casos y pasos sirve para problemas con transporte, banca, vivienda o salud."}$a3sld$::jsonb,5),
('como-presentar-un-reclamo-de-consumo-paso-a-paso','derecho',array['sociedad','negocios']::text[],'Cómo presentar un reclamo de consumo paso a paso','Explica con un mapa claro cómo se presenta un reclamo de consumo, primero ante la empresa y luego ante la entidad de protección al consumidor, con plazos, documentos y resultados posibles.','Guía','~20 h',20,array['Reclamos','Procedimiento']::text[],array['resolver','crear']::text[],'publicos',NULL,'derecho administracion comunicaciones trabajo social ciencias politicas ingenieria de sistemas educacion economia lectura de procedimientos. diagramas de flujo. redaccion clara. diseno de guias. portales oficiales. un editor de diagramas. un editor de documentos.',$a4sld${"id": "como-presentar-un-reclamo-de-consumo-paso-a-paso", "area": "derecho", "areas2": ["sociedad", "negocios"], "titulo": "Cómo presentar un reclamo de consumo paso a paso", "resumen": "Explica con un mapa claro cómo se presenta un reclamo de consumo, primero ante la empresa y luego ante la entidad de protección al consumidor, con plazos, documentos y resultados posibles.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Reclamos", "Procedimiento"], "intencion": ["resolver", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Comunicaciones", "Trabajo Social", "Ciencias Políticas", "Ingeniería de Sistemas", "Educación", "Economía"], "problema": ["Presentar un reclamo suele intimidar: no se sabe por dónde empezar, qué documentos llevar ni cuánto tarda. Eso hace que muchas personas desistan aunque tengan razón.", "Una guía paso a paso, bien ordenada, reduce el miedo y la confusión."], "desarrollar": ["Con fuentes oficiales, reconstruye el camino de un reclamo de consumo desde el primer contacto con el proveedor hasta una eventual presentación ante la autoridad, con los pasos, plazos y documentos de cada etapa.", "Dibuja un diagrama de flujo, redacta una guía en lenguaje sencillo y prepara un ejemplo completo de reclamo con un caso inventado."], "ampliaciones": [{"titulo": "Libro de reclamaciones", "aporta": "explica cómo se usa y qué pasa después."}, {"titulo": "Formularios", "aporta": "diseña una hoja con los datos que conviene tener a la mano."}, {"titulo": "Versión audiovisual", "aporta": "crea un video o una infografía corta del proceso."}], "objetivos": ["Reconstruir un procedimiento oficial.", "Representarlo en un diagrama.", "Explicarlo en lenguaje sencillo.", "Aplicarlo a un caso."], "habilidades": ["Lectura de procedimientos.", "Diagramas de flujo.", "Redacción clara.", "Diseño de guías."], "herramientas": ["Portales oficiales.", "Un editor de diagramas.", "Un editor de documentos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "El mismo mapa de procedimiento sirve para reclamos de salud, de servicios públicos, de educación o de banca."}$a4sld$::jsonb,6),
('reclamo-queja-y-denuncia-en-que-se-diferencian','derecho',array['sociedad']::text[],'Reclamo, queja y denuncia: ¿en qué se diferencian?','Aclara con ejemplos las diferencias entre un reclamo, una queja y una denuncia, quién los atiende y cuándo conviene usar cada uno.','Guía','~14 h',14,array['Reclamo','Queja']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion ciencias politicas comunicaciones trabajo social economia sociologia educacion lectura de normas. comparacion conceptual. redaccion clara. pensamiento juridico basico. portales oficiales. una tabla comparativa. un editor de tarjetas.',$a5sld${"id": "reclamo-queja-y-denuncia-en-que-se-diferencian", "area": "derecho", "areas2": ["sociedad"], "titulo": "Reclamo, queja y denuncia: ¿en qué se diferencian?", "resumen": "Aclara con ejemplos las diferencias entre un reclamo, una queja y una denuncia, quién los atiende y cuándo conviene usar cada uno.", "tipo": "Guía", "tiempo": "~14 h", "horas": 14, "etiquetas": ["Reclamo", "Queja"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Ciencias Políticas", "Comunicaciones", "Trabajo Social", "Economía", "Sociología", "Educación"], "problema": ["En la vida diaria se usan estas palabras como sinónimos, pero en el ámbito legal y administrativo cada una tiene un sentido y un camino distinto. Usar la figura equivocada puede hacer que el pedido se demore o no se atienda.", "Distinguirlas ayuda a elegir bien dónde y cómo presentar un problema."], "desarrollar": ["Con fuentes oficiales, define cada término, quién lo recibe, qué busca y qué respuesta puede dar, y arma una tabla comparativa.", "Redacta ocho situaciones cotidianas y clasifica cuál sería la figura adecuada en cada una, explicando por qué, y revisa tu guía con dos compañeros para ver si se entiende."], "ampliaciones": [{"titulo": "Mapa por institución", "aporta": "indica qué institución atiende cada figura."}, {"titulo": "Ejemplos escritos", "aporta": "redacta un modelo de cada uno."}, {"titulo": "Juego de clasificación", "aporta": "crea tarjetas para que otros practiquen."}], "objetivos": ["Definir términos legales con claridad.", "Comparar figuras.", "Clasificar casos.", "Validar con lectores."], "habilidades": ["Lectura de normas.", "Comparación conceptual.", "Redacción clara.", "Pensamiento jurídico básico."], "herramientas": ["Portales oficiales.", "Una tabla comparativa.", "Un editor de tarjetas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "La misma distinción de términos sirve para entender recursos administrativos, procesos judiciales o procedimientos internos de una universidad."}$a5sld$::jsonb,7),
('que-puede-hacer-un-consumidor-cuando-un-negocio-no-respeta-el-pr','derecho',array['negocios']::text[],'¿Qué puede hacer un consumidor cuando un negocio no respeta el precio anunciado?','Analiza qué ocurre cuando el precio que se paga es distinto al anunciado en la vitrina, el estante o la publicidad, y qué pasos puede seguir quien lo detecta.','Guía','~12 h',12,array['Precios','Consumidor']::text[],array['resolver','investigar']::text[],'publicos',NULL,'derecho economia administracion marketing comunicaciones contabilidad trabajo social educacion lectura de normas. analisis de casos. redaccion clara. diseno de infografias. portales oficiales. un editor de infografias. casos inventados.',$a6sld${"id": "que-puede-hacer-un-consumidor-cuando-un-negocio-no-respeta-el-pr", "area": "derecho", "areas2": ["negocios"], "titulo": "¿Qué puede hacer un consumidor cuando un negocio no respeta el precio anunciado?", "resumen": "Analiza qué ocurre cuando el precio que se paga es distinto al anunciado en la vitrina, el estante o la publicidad, y qué pasos puede seguir quien lo detecta.", "tipo": "Guía", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Precios", "Consumidor"], "intencion": ["resolver", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Economía", "Administración", "Marketing", "Comunicaciones", "Contabilidad", "Trabajo Social", "Educación"], "problema": ["A veces el precio del estante no coincide con el de la caja, o el anuncio de internet no es el que cobran al final. En muchos casos la persona paga sin reclamar o discute sin saber qué dice la norma.", "Conocer la regla general sobre precios anunciados y cómo dejar constancia permite actuar con tranquilidad."], "desarrollar": ["Con fuentes oficiales, resume qué dice la normativa sobre precios y publicidad, qué se espera de los negocios y qué opciones tiene el consumidor.", "Redacta tres casos inventados, en tienda, en supermercado y por internet, y para cada uno escribe qué pruebas reunir, cómo plantear el problema en el momento y qué hacer si no se resuelve."], "ampliaciones": [{"titulo": "Verificación en la tienda", "aporta": "sal a observar si los precios anunciados coinciden con los de caja, sin identificar negocios."}, {"titulo": "Frases útiles", "aporta": "arma una lista de frases claras para pedir la corrección."}, {"titulo": "Resumen para redes", "aporta": "diseña una infografía breve con tus conclusiones."}], "objetivos": ["Conocer reglas sobre precios anunciados.", "Aplicarlas a casos.", "Definir pasos y pruebas.", "Comunicar de forma sencilla."], "habilidades": ["Lectura de normas.", "Análisis de casos.", "Redacción clara.", "Diseño de infografías."], "herramientas": ["Portales oficiales.", "Un editor de infografías.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Si haces observación en tiendas, no nombres negocios ni tomes fotos de personas, y evita acusarlos: usa casos inventados para la guía.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "El mismo análisis sirve para discrepancias entre lo anunciado y lo cobrado en transporte, servicios o cuotas."}$a6sld$::jsonb,8),
('que-derechos-tiene-una-persona-cuando-compra-por-internet','derecho',array['tecnologia','negocios']::text[],'¿Qué derechos tiene una persona cuando compra por internet?','Explica qué derechos y precauciones tiene quien compra en línea, como información clara, entrega, devolución, arrepentimiento y seguridad de los pagos, con casos reales de uso.','Guía','~18 h',18,array['Comercio electrónico','Consumidor']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho ingenieria de sistemas economia administracion marketing comunicaciones ciencia de datos educacion lectura de normas. analisis de riesgos. diseno de guias. pensamiento critico. portales oficiales. un editor de infografias. casos inventados.',$a7sld${"id": "que-derechos-tiene-una-persona-cuando-compra-por-internet", "area": "derecho", "areas2": ["tecnologia", "negocios"], "titulo": "¿Qué derechos tiene una persona cuando compra por internet?", "resumen": "Explica qué derechos y precauciones tiene quien compra en línea, como información clara, entrega, devolución, arrepentimiento y seguridad de los pagos, con casos reales de uso.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Comercio electrónico", "Consumidor"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ingeniería de Sistemas", "Economía", "Administración", "Marketing", "Comunicaciones", "Ciencia de Datos", "Educación"], "problema": ["Comprar por internet es cómodo, pero también más arriesgado: el producto no se ve, el vendedor puede ser desconocido y las condiciones de entrega o devolución no siempre están claras.", "Saber qué se puede exigir y cómo reconocer tiendas confiables evita pérdidas y ayuda a reclamar a tiempo."], "desarrollar": ["Con fuentes oficiales, resume los derechos básicos del consumidor en compras a distancia, qué información debe dar el vendedor y qué opciones existen ante demoras, productos distintos o falta de entrega.", "Arma una lista de verificación antes de comprar, redacta tres casos inventados con su solución y presenta todo en una guía visual para estudiantes."], "ampliaciones": [{"titulo": "Señales de alerta", "aporta": "elabora una lista de indicios de una tienda poco confiable."}, {"titulo": "Medios de pago", "aporta": "compara riesgos de pagar con tarjeta, contra entrega o billetera digital."}, {"titulo": "Compra en el extranjero", "aporta": "añade qué cambia cuando el vendedor está en otro país."}], "objetivos": ["Conocer derechos en compras a distancia.", "Elaborar una lista de verificación.", "Analizar casos.", "Explicar con claridad."], "habilidades": ["Lectura de normas.", "Análisis de riesgos.", "Diseño de guías.", "Pensamiento crítico."], "herramientas": ["Portales oficiales.", "Un editor de infografías.", "Casos inventados."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "No incluyas datos de tarjetas, cuentas ni direcciones reales, y no promociones tiendas concretas."], "otroSector": "La misma guía sirve para reconocer riesgos en contratar servicios digitales, suscripciones o alquileres publicados en internet."}$a7sld$::jsonb,9),
('que-informacion-debe-dar-un-negocio-antes-de-vender-un-producto','derecho',array['negocios','sociedad']::text[],'¿Qué información debe dar un negocio antes de vender un producto o servicio?','Descubre qué datos debe informar un negocio antes de la venta, como precio, características, condiciones y riesgos, y revisa con una lista si un negocio lo cumple.','Guía','~15 h',15,array['Información','Transparencia']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion marketing economia comunicaciones contabilidad ingenieria industrial educacion lectura de normas. diseno de listas de verificacion. analisis de documentos. comunicacion clara. portales oficiales. hoja de calculo o documento. ejemplos de avisos publicos.',$a8sld${"id": "que-informacion-debe-dar-un-negocio-antes-de-vender-un-producto", "area": "derecho", "areas2": ["negocios", "sociedad"], "titulo": "¿Qué información debe dar un negocio antes de vender un producto o servicio?", "resumen": "Descubre qué datos debe informar un negocio antes de la venta, como precio, características, condiciones y riesgos, y revisa con una lista si un negocio lo cumple.", "tipo": "Guía", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Información", "Transparencia"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Marketing", "Economía", "Comunicaciones", "Contabilidad", "Ingeniería Industrial", "Educación"], "problema": ["Decidir una compra exige información clara: cuánto cuesta realmente, qué incluye, cuáles son las condiciones y qué riesgos tiene. Cuando falta algo, el consumidor decide a ciegas.", "También sirve a los emprendedores, porque informar bien evita reclamos y genera confianza."], "desarrollar": ["Con fuentes oficiales, lista la información que debe darse según el tipo de producto o servicio, y arma una lista de verificación de entre diez y quince puntos.", "Aplica la lista a ejemplos públicos o inventados, como un aviso de internet o un cartel, marca qué información falta y redacta recomendaciones para mejorarlos."], "ampliaciones": [{"titulo": "Para emprendedores", "aporta": "adapta la lista como guía para quien inicia un negocio."}, {"titulo": "Letra pequeña", "aporta": "analiza cómo se presentan las condiciones y si se leen."}, {"titulo": "Comparar sectores", "aporta": "compara cuánta información se da en alimentos, tecnología y servicios."}], "objetivos": ["Conocer obligaciones de información.", "Elaborar una lista de verificación.", "Aplicarla a ejemplos.", "Recomendar mejoras."], "habilidades": ["Lectura de normas.", "Diseño de listas de verificación.", "Análisis de documentos.", "Comunicación clara."], "herramientas": ["Portales oficiales.", "Hoja de cálculo o documento.", "Ejemplos de avisos públicos."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian.", "Si analizas avisos reales, no los atribuyas a negocios identificables ni los uses para acusar."], "otroSector": "La misma lista de verificación sirve para evaluar la información de un curso, de una app o de una oferta de prácticas."}$a8sld$::jsonb,10),
('que-revisar-antes-de-firmar-un-contrato-de-alquiler','derecho',array['sociedad','negocios']::text[],'Qué revisar antes de firmar un contrato de alquiler','Aprende los términos más comunes de un contrato de alquiler, como garantía, plazo, renta, penalidades y reparaciones, y arma una lista para revisar antes de firmar.','Guía','~18 h',18,array['Alquiler','Contratos']::text[],array['investigar','resolver']::text[],'publicos',NULL,'derecho economia arquitectura administracion contabilidad trabajo social sociologia ingenieria civil lectura contractual basica. analisis de riesgos. diseno de listas. redaccion clara. modelos publicos de contratos. un editor de documentos. hoja de calculo.',$a9sld${"id": "que-revisar-antes-de-firmar-un-contrato-de-alquiler", "area": "derecho", "areas2": ["sociedad", "negocios"], "titulo": "Qué revisar antes de firmar un contrato de alquiler", "resumen": "Aprende los términos más comunes de un contrato de alquiler, como garantía, plazo, renta, penalidades y reparaciones, y arma una lista para revisar antes de firmar.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Alquiler", "Contratos"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Economía", "Arquitectura", "Administración", "Contabilidad", "Trabajo Social", "Sociología", "Ingeniería Civil"], "problema": ["Para muchos jóvenes, alquilar es la primera vez que firman un contrato importante. Se firma con prisa y sin entender cláusulas sobre garantía, aumentos, plazos de salida o quién paga las reparaciones.", "Entender el contrato antes de firmar evita conflictos y pérdidas de dinero."], "desarrollar": ["Con modelos públicos de contratos y guías oficiales, identifica los términos más comunes, explícalos en lenguaje sencillo y señala qué suele generar problemas.", "Elabora una lista de verificación para revisar un contrato de alquiler y aplícala a un contrato modelo, marcando qué cláusulas preguntarías o negociarías."], "ampliaciones": [{"titulo": "Inventario del inmueble", "aporta": "diseña una hoja para registrar el estado al entrar."}, {"titulo": "Cuánto cuesta entrar", "aporta": "calcula los pagos iniciales, como adelanto y garantía."}, {"titulo": "Salida del contrato", "aporta": "explica qué pasa si se quiere terminar antes de tiempo."}], "objetivos": ["Comprender términos de un contrato de alquiler.", "Detectar cláusulas críticas.", "Elaborar una lista de verificación.", "Explicarlo con claridad."], "habilidades": ["Lectura contractual básica.", "Análisis de riesgos.", "Diseño de listas.", "Redacción clara."], "herramientas": ["Modelos públicos de contratos.", "Un editor de documentos.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Usa modelos de contratos públicos o inventados y no incluyas datos de arrendadores ni inquilinos reales.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "La misma lista sirve para revisar contratos de internet, de gimnasio, de servicios educativos o de trabajo."}$a9sld$::jsonb,11),
('comparando-distintos-tipos-de-contratos-de-servicios','derecho',array['negocios']::text[],'Comparando distintos tipos de contratos de servicios','Compara contratos de servicios de uso común, como internet, telefonía, gimnasio o seguros, y descubre qué obligaciones, penalidades y condiciones de salida tiene cada uno.','Análisis','~18 h',18,array['Contratos','Servicios']::text[],array['investigar']::text[],'publicos',NULL,'derecho administracion economia contabilidad ingenieria de sistemas ingenieria industrial comunicaciones marketing lectura de contratos. analisis comparativo. calculo de costos. pensamiento critico. una tabla comparativa. condiciones publicas de las empresas. hoja de calculo.',$a10sld${"id": "comparando-distintos-tipos-de-contratos-de-servicios", "area": "derecho", "areas2": ["negocios"], "titulo": "Comparando distintos tipos de contratos de servicios", "resumen": "Compara contratos de servicios de uso común, como internet, telefonía, gimnasio o seguros, y descubre qué obligaciones, penalidades y condiciones de salida tiene cada uno.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Contratos", "Servicios"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Economía", "Contabilidad", "Ingeniería de Sistemas", "Ingeniería Industrial", "Comunicaciones", "Marketing"], "problema": ["Casi todos firmamos o aceptamos contratos de servicios sin leerlos. Pero esas condiciones incluyen plazos mínimos, penalidades por terminar antes, aumentos de precio y renovaciones automáticas.", "Compararlos muestra qué ofrece cada tipo de servicio y qué parte del riesgo asume la persona."], "desarrollar": ["Reúne las condiciones públicas de cuatro tipos de servicios y resume en una tabla el plazo, las obligaciones de cada parte, las penalidades, cómo se cancela y cómo se resuelven los problemas.", "Identifica las cláusulas más favorables y las más exigentes para el usuario, y explica por qué algunos servicios son más fáciles de dejar que otros."], "ampliaciones": [{"titulo": "Renovación automática", "aporta": "analiza cuántos contratos se renuevan sin avisar."}, {"titulo": "Costo total del contrato", "aporta": "calcula cuánto se paga en todo el plazo."}, {"titulo": "Cómo cancelar", "aporta": "arma pasos para cancelar cada servicio."}], "objetivos": ["Reunir condiciones públicas de contratos.", "Comparar cláusulas.", "Identificar obligaciones y riesgos.", "Concluir con criterios."], "habilidades": ["Lectura de contratos.", "Análisis comparativo.", "Cálculo de costos.", "Pensamiento crítico."], "herramientas": ["Una tabla comparativa.", "Condiciones públicas de las empresas.", "Hoja de cálculo."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "No califiques a empresas específicas como abusivas: describe lo que dicen sus documentos públicos con su fecha.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "La misma comparación sirve para contratos de seguros, de préstamos o de servicios digitales."}$a10sld$::jsonb,12),
('clausulas-frecuentes-en-contratos-cotidianos-y-de-prestacion-de','derecho',array['negocios']::text[],'Cláusulas frecuentes en contratos cotidianos y de prestación de servicios','Explica con ejemplos las cláusulas que más aparecen en contratos de la vida diaria y de servicios profesionales, como objeto, plazo, pago, penalidades, confidencialidad y resolución.','Guía','~20 h',20,array['Cláusulas','Contratos']::text[],array['investigar','crear']::text[],'publicos',NULL,'derecho administracion economia contabilidad ingenieria de sistemas comunicaciones ingenieria industrial educacion lectura contractual. redaccion clara. analisis de riesgos. diseno de guias. modelos publicos de contratos. un editor de documentos. un editor de infografias.',$a11sld${"id": "clausulas-frecuentes-en-contratos-cotidianos-y-de-prestacion-de", "area": "derecho", "areas2": ["negocios"], "titulo": "Cláusulas frecuentes en contratos cotidianos y de prestación de servicios", "resumen": "Explica con ejemplos las cláusulas que más aparecen en contratos de la vida diaria y de servicios profesionales, como objeto, plazo, pago, penalidades, confidencialidad y resolución.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Cláusulas", "Contratos"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Administración", "Economía", "Contabilidad", "Ingeniería de Sistemas", "Comunicaciones", "Ingeniería Industrial", "Educación"], "problema": ["Los contratos tienen una estructura repetida, pero cada cláusula puede cambiar mucho el equilibrio entre las partes. Un freelance que no revisa la cláusula de pago o de propiedad de lo creado puede perder dinero y derechos.", "Conocer las cláusulas más comunes ayuda a leer cualquier contrato con más seguridad."], "desarrollar": ["Elige entre ocho y diez cláusulas frecuentes y, para cada una, explica en lenguaje sencillo qué dice, para qué sirve, qué riesgos puede tener y qué preguntas hacer, con ejemplos inventados.", "Aplica la guía a un contrato de prestación de servicios modelo, subraya las cláusulas clave y escribe qué cambiarías o preguntarías."], "ampliaciones": [{"titulo": "Glosario", "aporta": "crea un glosario ilustrado de términos contractuales."}, {"titulo": "Semáforo de riesgo", "aporta": "clasifica cláusulas en verde, amarillo y rojo."}, {"titulo": "Para freelancers", "aporta": "adapta la guía a quienes trabajan por encargo."}], "objetivos": ["Reconocer cláusulas comunes.", "Explicarlas en lenguaje sencillo.", "Evaluar sus riesgos.", "Aplicarlas a un contrato modelo."], "habilidades": ["Lectura contractual.", "Redacción clara.", "Análisis de riesgos.", "Diseño de guías."], "herramientas": ["Modelos públicos de contratos.", "Un editor de documentos.", "Un editor de infografías."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Usa modelos públicos o inventados, y no copies contratos reales con datos de personas.", "Verifica siempre en fuentes oficiales que la norma siga vigente y cita su fecha, porque las leyes cambian."], "otroSector": "La misma guía de cláusulas sirve para convenios, acuerdos entre estudiantes o términos de plataformas."}$a11sld$::jsonb,13),
('una-guia-para-comprender-contratos-antes-de-firmarlos','derecho',array['educacion','sociedad']::text[],'Una guía para comprender contratos antes de firmarlos','Crea una guía corta y visual para estudiantes que explique qué preguntas hacerse antes de firmar cualquier contrato: qué me comprometo, por cuánto tiempo, qué pasa si incumplo y cómo salgo.','Guía','~18 h',18,array['Contratos','Guía']::text[],array['crear']::text[],'publicos',NULL,'derecho educacion comunicaciones administracion diseno psicologia trabajo social ingenieria de sistemas diseno de materiales. pruebas con usuarios. redaccion clara. pensamiento critico. un editor de infografias. un contrato modelo. un formulario de opinion.',$a12sld${"id": "una-guia-para-comprender-contratos-antes-de-firmarlos", "area": "derecho", "areas2": ["educacion", "sociedad"], "titulo": "Una guía para comprender contratos antes de firmarlos", "resumen": "Crea una guía corta y visual para estudiantes que explique qué preguntas hacerse antes de firmar cualquier contrato: qué me comprometo, por cuánto tiempo, qué pasa si incumplo y cómo salgo.", "tipo": "Guía", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Contratos", "Guía"], "intencion": ["crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Educación", "Comunicaciones", "Administración", "Diseño", "Psicología", "Trabajo Social", "Ingeniería de Sistemas"], "problema": ["Se firman contratos con la misma facilidad con la que se acepta una aplicación: sin leer. Pero un contrato es un compromiso con consecuencias, y los jóvenes suelen ser los menos informados.", "Una guía sencilla con pocas preguntas clave puede tener mucho efecto práctico."], "desarrollar": ["Define entre siete y diez preguntas clave que cualquiera debería hacerse antes de firmar, como qué estoy aceptando, cuánto pago en total, cuánto dura, cómo termino y quién responde si algo falla.", "Diseña la guía como un folleto o una infografía, pruébala con cinco personas pidiéndoles que la usen con un contrato modelo y ajústala según lo que no se entienda."], "ampliaciones": [{"titulo": "Tarjeta de bolsillo", "aporta": "resume la guía en una tarjeta de cinco preguntas."}, {"titulo": "Contratos digitales", "aporta": "adapta la guía para términos y condiciones de aplicaciones."}, {"titulo": "Juego de simulación", "aporta": "crea un juego de roles donde se firma un contrato."}], "objetivos": ["Formular preguntas clave.", "Diseñar una guía clara.", "Probarla con lectores.", "Mejorarla con la respuesta recibida."], "habilidades": ["Diseño de materiales.", "Pruebas con usuarios.", "Redacción clara.", "Pensamiento crítico."], "herramientas": ["Un editor de infografías.", "Un contrato modelo.", "Un formulario de opinión."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Usa un contrato modelo o inventado y pide permiso a las personas que prueben tu guía, sin recoger datos personales."], "otroSector": "La misma guía sirve para leer políticas de privacidad, ofertas de trabajo o reglamentos."}$a12sld$::jsonb,14),
('obligaciones-y-responsabilidades-en-acuerdos-comunes','derecho',array['sociedad']::text[],'Obligaciones y responsabilidades en acuerdos comunes','Analiza qué obligaciones y responsabilidades nacen de acuerdos cotidianos, como prestar dinero, compartir un departamento o hacer un trabajo grupal, y qué pasa cuando alguien no cumple.','Análisis','~18 h',18,array['Obligaciones','Acuerdos']::text[],array['investigar']::text[],'ficticios',NULL,'derecho filosofia sociologia administracion psicologia trabajo social educacion economia analisis de casos. pensamiento juridico basico. redaccion clara. resolucion de conflictos. un editor de documentos. casos inventados. un editor de esquemas.',$a13sld${"id": "obligaciones-y-responsabilidades-en-acuerdos-comunes", "area": "derecho", "areas2": ["sociedad"], "titulo": "Obligaciones y responsabilidades en acuerdos comunes", "resumen": "Analiza qué obligaciones y responsabilidades nacen de acuerdos cotidianos, como prestar dinero, compartir un departamento o hacer un trabajo grupal, y qué pasa cuando alguien no cumple.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Obligaciones", "Acuerdos"], "intencion": ["investigar"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Derecho", "Filosofía", "Sociología", "Administración", "Psicología", "Trabajo Social", "Educación", "Economía"], "problema": ["Hacemos acuerdos todo el tiempo, algunos por escrito y otros de palabra. Muchas veces nadie sabe con claridad qué se prometió, qué pasa si alguien incumple o quién debe asumir un costo.", "Entender cómo funcionan las obligaciones permite hacer acuerdos más claros y evitar conflictos."], "desarrollar": ["Redacta seis acuerdos cotidianos inventados, como un préstamo entre amigos, un alquiler de cuarto o un trabajo compartido, e identifica para cada uno quién debe qué, cuándo y qué pasa si no se cumple.", "Propón para cada caso una forma sencilla de dejar el acuerdo claro, como un mensaje, un registro o un documento breve, y explica qué lo haría exigible."], "ampliaciones": [{"titulo": "Acuerdo verbal frente a escrito", "aporta": "compara qué cambia en la práctica."}, {"titulo": "Consecuencias", "aporta": "analiza qué pasa ante el incumplimiento en cada caso."}, {"titulo": "Plantillas", "aporta": "diseña modelos simples de acuerdo para casos frecuentes."}], "objetivos": ["Identificar obligaciones en acuerdos cotidianos.", "Reconocer responsabilidades.", "Proponer formas de dejarlos claros.", "Explicar consecuencias."], "habilidades": ["Análisis de casos.", "Pensamiento jurídico básico.", "Redacción clara.", "Resolución de conflictos."], "herramientas": ["Un editor de documentos.", "Casos inventados.", "Un editor de esquemas."], "lineamientos": ["Es material informativo y educativo, no asesoría legal: para un caso real conviene consultar a un abogado o a la entidad competente.", "Trabaja con casos inventados o públicos y no incluyas datos personales de personas reales."], "otroSector": "El mismo análisis sirve para acuerdos de trabajo en equipo, convenios entre organizaciones o reglas de convivencia."}$a13sld$::jsonb,15)
